def load(name):
    return json.loads((ROOT / name).read_text(encoding='utf8'))


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--write', action='store_true')
    a = p.parse_args()
    data = load('continuation_terms.en.json')
    existing = {e['id']: e for e in data['entries']}
    added = []
    for entry in ENTRIES:
        if entry['id'] in existing:
            if existing[entry['id']] != entry:
                raise ValueError('Existing term differs; review explicitly')
        else:
            added.append(entry)
    data['entries'].extend(added)
    profiles = load('heroes_phantasia.en.json')
    executable = load('executable_terms.en.json')
    updates = []

    def update(dataset, identity, english, values):
        row = next(e for e in dataset['entries'] if e['id'] == identity)
        if row['en'] != english:
            raise ValueError('Profile identity differs')
        if 'sources' in values:
            values['sources'] = list(dict.fromkeys(row.get('sources', []) + values['sources']))
        if 'aliases' in values:
            values['aliases'] = list(dict.fromkeys(row.get('aliases', []) + values['aliases']))
        if any(row.get(k) != v for k, v in values.items()):
            updates.append(dict(id=identity, **values))
            row.update(values)

    update(profiles, 'character_085', 'Nao Yuuki', dict(nickname='Nao', gender='female', personality='Rebellious, cynical and sharp-tongued', role='Fuka Academy junior-high student and HiME; Julia wielder', sources=['https://mai.fandom.com/wiki/Mai-HiME_characters_(anime)', 'https://manga.fandom.com/wiki/Nao_Yuuki', 'https://www.sunrise-inc.co.jp/my-hime/web/character/chara/nao.html'], confidence=dict(appearance='high', name='high', gender='high', personality='researched', role='researched'), notes='Sunrise confirms name reading and female junior-high identity; franchise references corroborate English spelling and anime profile. Do not import manga-only relationships or My-Otome Juliet Nao Zhang identity.'))
    update(profiles, 'character_089', 'Julia', dict(context_required=True, full_name='Julia Silverstein', nickname='Julia (short name)', gender='female', personality='Dedicated to medical research', role='Red Shield medical doctor and chiropteran researcher', sources=['https://en.wikipedia.org/wiki/List_of_Blood%2B_characters', 'https://www.absoluteanime.com/blood%2B/julia'], confidence=dict(appearance='high', name='researched', gender='researched', personality='researched', role='researched'), notes='BLOOD+ doctor; use source short Julia, full Julia Silverstein where supplied. Distinct from the identically named My-HiME Child. Anime continuity; do not insert later allegiance or relationship events into dialogue.'))
    update(profiles, 'character_070', 'Lavie', dict(gender='female', personality='Sweet-natured, apologetic and perceptive', role="Kogoro's younger sister; supports the pair through part-time work", sources=['https://en.wikipedia.org/wiki/List_of_Sgt._Frog_characters'], confidence=dict(appearance='high', name='researched', gender='researched', personality='researched', role='researched'), notes='Use Lavie in anime continuity; Rabbie is an English manga variant. Do not substitute the unrelated Granzort character or insert later jobs into this game scene.'))
    update(profiles, 'character_056', 'So Kigetsuki', dict(nickname='Kik-kun (provisional affectionate rendering)', gender='male', personality='Self-absorbed, arrogant and misogynistic', role='HOLY member; creator of the Tokonatsu Sisters Alter dolls', sources=['https://en.wikipedia.org/wiki/List_of_S-CRY-ed_characters', 'https://scryed.fandom.com/wiki/Sou_Kigetsuki'], confidence=dict(appearance='high', name='researched', gender='researched', personality='researched', role='researched'), notes='Keep existing macronless So Kigetsuki and source short Kigetsuki. References also romanize the given name Sou or Sō. The sisters address him affectionately as Kik-kun in game-scene drafts; that nickname rendering is provisional. Do not import later allegiance or fate into this scene.'))
    update(executable, 'executable_character_048', 'Van Argiano', dict(aliases=['アルジャーノ'], sources=['https://bloodplusanime.fandom.com/wiki/Van_Argiano'], nickname='Argiano (surname address)', notes='Use Argiano for the short speaker label and Van Argiano for the full name. Name and scientist role are source-backed; preserve game-scene knowledge rather than importing later career changes.'))
    update(data, 'continuation_061', 'HiME', dict(full_name='Highly-advanced Materialising Equipment', sources=['https://www.sunrise-inc.co.jp/my-hime/web/art/yougo.html'], notes='Preserve capitalization; plural HiMEs where English grammar requires. Plain source HiME stays abbreviated. The official full expansion is used when the source supplies the full technical term or explicitly explains the acronym; do not invent additional lore.'))
    print(json.dumps(dict(added=added, profile_updates=updates), ensure_ascii=True, indent=2))
    if not a.write:
        print('DRY RUN: glossary unchanged.')
        return
    for name, dataset in [('continuation_terms.en.json', data), ('heroes_phantasia.en.json', profiles), ('executable_terms.en.json', executable)]:
        (ROOT / name).write_text(json.dumps(dataset, ensure_ascii=False, indent=2) + '\n', encoding='utf8')


if __name__ == '__main__':
    main()
